definition:
def max_box(pixels, font_metrics)
def max_box(nil, %FontMetrics{max_box: max_box}) do
  max_box
end
def max_box(
      pixels,
      %FontMetrics{max_box: {x_min, y_min, x_max, y_max}, units_per_em: u_p_m}
    ) do
  scale = pixels / u_p_m
  {x_min * scale, y_min * scale, x_max * scale, y_max * scale}
end

