def prewalk(node, fun) when is_function(fun, 1) do
  {node, _} =
    prewalk(node, nil, fn x, nil ->
      case fun.(x) do
        {:halt, x} -> {:halt, x, nil}
        x -> {x, nil}
      end
    end)

  node
end

