def do_run(input, %{validation_result_phase: abort_phase}) do
  {fragments, error_count} = check(input.fragments)
  result = %{input | fragments: fragments}

  if error_count > 0 do
    {:jump, result, abort_phase}
  else
    {:ok, result}
  end
end

