def peercert(socket) do
  case ThousandIsland.Socket.peercert(socket) do
    {:ok, cert} -> {:ok, cert}
    {:error, :no_peercert} -> {:ok, nil}
    {:error, :not_secure} -> {:ok, nil}
    {:error, reason} -> {:error, reason}
  end
end

