def decode(
      <<type::int8(), status::int8(), length::int16(), spid::int16(), package::int8(),
        window::int8()>>
    ) do
  case decode_type(type) do
    {^type, pkg_header_type, has_data} ->
      {:ok,
       %__MODULE__{
         type: pkg_header_type,
         status: decode_status(status),
         length: length - 8,
         spid: spid,
         package: package,
         window: window,
         has_data?: has_data
       }}

    {:error, _reason} = e ->
      e
  end
end

