def convert(
      %{calendar: calendar, hour: hour, minute: minute, second: second, microsecond: microsecond},
      calendar
    ) do
  time = %Time{
    calendar: calendar,
    hour: hour,
    minute: minute,
    second: second,
    microsecond: microsecond
  }

  {:ok, time}
end
def convert(%{microsecond: {_, precision}} = time, calendar) do
  {hour, minute, second, {microsecond, _}} =
    time |> to_day_fraction() |> calendar.time_from_day_fraction()

  time = %Time{
    calendar: calendar,
    hour: hour,
    minute: minute,
    second: second,
    microsecond: {microsecond, precision}
  }

  {:ok, time}
end

