def append_query(%URI{} = uri, query) when is_binary(query) and uri.query in [nil, ""] do
  %{uri | query: query}
end
def append_query(%URI{} = uri, query) when is_binary(query) do
  if String.ends_with?(uri.query, "&") do
    %{uri | query: uri.query <> query}
  else
    %{uri | query: uri.query <> "&" <> query}
  end
end

