def to_next_page(flop, total_pages \\ nil)
def to_next_page(%Flop{page: page} = flop, _) when is_integer(page) and page < 0 do
  %{flop | page: 1}
end
def to_next_page(%Flop{page: page} = flop, nil) do
  %{flop | page: page + 1}
end
def to_next_page(%Flop{page: page} = flop, total_pages)
    when is_integer(total_pages) and page < total_pages do
  %{flop | page: page + 1}
end
def to_next_page(%Flop{} = flop, total_pages) when is_integer(total_pages) do
  %{flop | page: total_pages}
end

