end
def handle_sqs_results({:ok, %{body: %{messages: messages}, status_code: 200}})
    when is_list(messages) do
  Logger.info("Received SQS messages, count=#{length(messages)}")
  {:ok, Enum.map(messages, &parse_message/1)}
end

