def dump_data(structure \\ structure()) do
  Map.new(structure, fn table ->
    columns_to_select = table.columns ++ table.optional_fkeys
    {table.name, table.name |> from(select: ^columns_to_select) |> Arrow.Repo.all()}
  end)
end

def with_latest_revision_ids(query \\ from(d in __MODULE__, as: :disruptions)) do
  latest_ids =
    from(r in DisruptionRevision,
      group_by: r.disruption_id,
      select: %{disruption_id: r.disruption_id, latest_revision_id: max(r.id)}
    )

  from([disruptions: d] in query,
    join: l in subquery(latest_ids),
    on: l.disruption_id == d.id,
    as: :latest_ids
  )
end

def first_last_trip_times(
      %__MODULE__{} = replacement_service,
      schedule_service_types \\ schedule_service_types()
    ) do
  schedule_service_types
  |> Enum.map(fn service_type ->
    service_type_abbreviation = service_type_to_workbook_abbreviation(service_type)

    day_of_week_data =
      Map.get(
        replacement_service.source_workbook_data,
        workbook_column_from_day_of_week(service_type_abbreviation)
      )

    {service_type, day_of_week_data}
  end)
  |> Enum.reject(&match?({_service_type, nil}, &1))
  |> Map.new(fn {service_type, day_of_week_data} ->
    {first_trips, last_trips, _headway_periods} =
      Enum.reduce(day_of_week_data, {%{}, %{}, %{}}, &reduce_workbook_data/2)

    {service_type, %{first_trips: first_trips, last_trips: last_trips}}
  end)
end

