def io_stream(body) when is_binary(body) do
  Stream.resource(
    fn ->
      {:ok, pid} = StringIO.open(body)
      pid
    end,
    fn pid ->
      case IO.read(pid, :line) do
        line when is_binary(line) -> {[line], pid}
        _ -> {:halt, pid}
      end
    end,
    fn pid -> StringIO.close(pid) end
  )
end

def init(url, opts) when is_binary(url) and is_list(opts) do
  state = %__MODULE__{url: url, parser: Keyword.fetch!(opts, :parser)}

  state =
    struct!(
      state,
      Keyword.take(opts, ~w(get_opts fetch_after content_warning_timeout headers)a)
    )

  state = %{state | headers: Concentrate.unwrap_values(state.headers)}
  state = %{state | last_success: now() - state.fetch_after - 1}

  case Keyword.get(opts, :fallback_url) do
    url when is_binary(url) -> %{state | fallback: {:not_active, url}}
    _ -> state
  end
end

