def vehicles_by_stop_direction_id(state) do
  Enum.map(state, fn {comment, vehicles} ->
    vehicles_by_stop =
      Enum.reduce(vehicles, %{}, fn v, acc ->
        update_in(acc, [{v.stop_id, v.trip.direction_id}], fn vs -> [v | vs || []] end)
      end)

    {comment, vehicles_by_stop}
  end)
end

def init(:ok) do
  {:ok, %{vehicles: %{}, trip_updates: %{}}}
end

def init(url, opts) when is_binary(url) and is_list(opts) do
  state = %__MODULE__{url: url, parser: Keyword.fetch!(opts, :parser)}

  state =
    struct!(
      state,
      Keyword.take(opts, ~w(get_opts fetch_after content_warning_timeout headers)a)
    )

  state = %{state | last_success: now() - state.fetch_after - 1}

  case Keyword.get(opts, :fallback_url) do
    url when is_binary(url) -> %{state | fallback: {:not_active, url}}
    _ -> state
  end
end

def empty do
  %JsonApi{links: %{}, data: []}
end

def merge(j1, j2) do
  %JsonApi{links: Map.merge(j1.links, j2.links), data: j1.data ++ j2.data}
end

def direction_attrs([zero, one], route_patterns) do
  %{
    0 => maybe_direction_attr(0, zero, route_patterns),
    1 => maybe_direction_attr(1, one, route_patterns)
  }
end

def by_type_uncached(types) do
  case all() do
    [] -> {:error, "no routes"}
    routes -> {:ok, Enum.filter(routes, fn route -> route.type in types end)}
  end
end

def fetch_connecting_routes_via_stop(
      %JsonApi.Item{
        relationships: %{
          "stop" => [%JsonApi.Item{relationships: %{"connecting_stops" => connecting_stops}}]
        }
      } = route
    ) do
  Enum.flat_map(connecting_stops, fn %JsonApi.Item{id: stop_id} ->
    case MBTAV3API.Routes.by_stop(stop_id) do
      %JsonApi{data: data} -> data
      _ -> []
    end
  end) ++ [route]
end
def fetch_connecting_routes_via_stop(route) do
  [route]
end

