def perform_write(payload, now) do
  fcm_token = payload.fcm_token

  Repo.transact(fn ->
    user =
      Repo.one(
        from(u in User,
          where: u.fcm_token == ^fcm_token,
          preload: [notification_subscriptions: :windows]
        )
      )
      |> case do
        nil -> %User{fcm_token: fcm_token}
        user -> user
      end

    changeset =
      user |> Ecto.Changeset.change(fcm_last_verified: now) |> WritePayload.changeset(payload)

    case Repo.insert_or_update(changeset) do
      {:ok, _} -> {:ok, :ok}
      {:error, error} -> {:error, error}
    end
  end)
end

def last_schedule_grouping(schedule, nil) do
  {schedule.route_id, nil}
end
def last_schedule_grouping(schedule, trip) do
  {schedule.route_id, trip.direction_id}
end

def get_edges(data) do
  case data do
    %{"data" => %{"nearest" => %{"edges" => edges}}} -> {:ok, edges}
    _ -> {:error, :bad_format}
  end
end

def get_stop(edge) do
  case edge do
    %{"node" => %{"place" => stop}} -> {:ok, stop}
    _ -> {:error, :bad_format}
  end
end

def parse_edges(edges) do
  edges
  |> Enum.reduce({:ok, []}, fn
    edge, {:ok, reversed_stops} ->
      with {:ok, stop} <- get_stop(edge),
           {:ok, stop} <- parse_stop(stop) do
        {:ok, [stop | reversed_stops]}
      else
        :ignore -> {:ok, reversed_stops}
        {:error, error} -> {:error, error}
      end

    _edge, {:error, error} ->
      {:error, error}
  end)
  |> case do
    {:ok, reversed_stops} -> {:ok, Enum.reverse(reversed_stops)}
    {:error, error} -> {:error, error}
  end
end

def request(latitude, longitude, radius) do
  Req.new(method: :post)
  |> AbsintheClient.attach(
    graphql: {graphql_query(), %{latitude: latitude, longitude: longitude, radius: radius}}
  )
end

def ok_response(data, included \\ []) do
  {:ok,
   %MBTAV3API.JsonApi.Response{
     data: data,
     included: MBTAV3API.JsonApi.Object.to_full_map(included)
   }}
end
